parameters.jsCode:
const input = $input.first().json;
const question = String(input.question ?? '').replace(/\s+/g, ' ').trim();
const audience = String(input.audience ?? '').replace(/\s+/g, ' ').trim();
const sources = Array.isArray(input.sources) ? input.sources.filter((source) => source && source.id && source.title && source.text).map((source) => ({ id: String(source.id), title: String(source.title).trim(), text: String(source.text).replace(/\s+/g, ' ').trim() })) : [];
const missing = [];
if (!question) missing.push('question');
if (!sources.length) missing.push('sources');
return [{ json: { ...input, question, audience, sources, sourceCount: sources.length, missingFields: missing, inputValid: missing.length === 0 && question.length >= 15 } }];

const research = $input.first().json;
const qualityIssues = [];
if (!research.inputValid) qualityIssues.push('Research question or sources are missing or too short');
if (research.sources.length < 2) qualityIssues.push('Fewer than two sources were provided');
const sourceText = research.sources.map((source) => source.text.toLowerCase()).join(' ');
if (sourceText.length < 80) qualityIssues.push('Evidence context is unusually short');
return [{ json: { ...research, qualityIssues, evidenceQuality: qualityIssues.length === 0 ? 'usable_demo_evidence' : 'limited_demo_evidence', requiresHumanReview: qualityIssues.length > 0 } }];

