const research = $items('Evidence Quality Gate')[0].json;
const raw = String($input.first().json.text ?? $input.first().json.response ?? '');
let parsed;
try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = { summary: 'The model did not return a valid structured brief.', keyFindings: [], sourceComparison: [], confidence: 'low', limitations: ['Invalid structured AI output'], sourcesUsed: [] };
}
const limitations = Array.isArray(parsed.limitations) ? [...parsed.limitations] : [];
if (research.qualityIssues.length) limitations.push(...research.qualityIssues);
const needsHumanReview = Boolean(research.requiresHumanReview) || research.qualityIssues.length > 0 || parsed.confidence === 'low' || !parsed.summary;
return [{ json: { researchId: research.researchId, question: research.question, audience: research.audience, summary: parsed.summary ?? '', keyFindings: parsed.keyFindings ?? [], sourceComparison: parsed.sourceComparison ?? [], confidence: parsed.confidence ?? 'low', needsHumanReview, limitations, sourcesUsed: parsed.sourcesUsed ?? [], safetyNote: 'Closed-set draft only. No web search, external API, or publication was performed.' } }];
